import {
  Component,
  Host,
  h,
  Prop,
  Event,
  EventEmitter,
  State,
  Element,
  Listen,
  ComponentInterface,
  VNode,
} from '@stencil/core';
import { BtnVariant, BtnSize } from '@src/components/ks-button/types';
import { DropdownPopoverProps, DropdownSearchConfig } from '@src/components/ks-dropdown-menu/types';
import { DropdownItem } from '@src/components/ks-dropdown-menu-list/types';
import { Placement } from '@floating-ui/dom';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { sendActionTracking, sendDurationTracking, sendExposeTracking } from '@src/shared/unclassified/tracking';
import { Slot, Slots, Vue2ValueFix, Uncontrollable } from '@src/framework/decorators';
import { Value } from 'async-validator';
import { DetailArgs } from '@src/shared/dom';
import { DropdownButtonPartProps } from './types';
import { getPartProps } from '@src/shared/base-props';
import { FlattenNode } from '@src/components/ks-tree-view/utils';
import { noop } from 'lodash-es';
import { KsDropdownMenu } from '@src/components/ks-dropdown-menu';
import { KsIconChevronDown } from '@fe-infra/keystone-icons-stencil';

const prefix = 'dropdown-button';

/**
 * @slot default - Trigger content rendered inside the dropdown button before the chevron icon.
 * @slot popupFooter - Slot for custom footer content rendered at the bottom of the dropdown menu.
 * @slot listHeader - Slot for custom header content rendered at the top of the list area.
 * @slot empty - Slot for custom content when the list is empty.
 * @slot loadFailure - Slot for custom content when the list fails to load.
 * @slot loadMoreFailure - Slot for custom content when the list fails to load more items.
 * @part button - The trigger button element.
 */
@Component({
  tag: 'ks-dropdown-button',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsDropdownButton implements ComponentInterface {
  protected static vModel = { prop: 'value', event: 'ksChange' };
  @Element() el!: HTMLKsDropdownButtonElement;
  private dropdownMenuRef!: HTMLKsDropdownMenuElement;

  // 透传 dropdown-menu 的所有属性
  /** The options rendered in the dropdown menu list. */
  @Prop() options?: KsDropdownMenu['options'];
  /** The tab options rendered in the dropdown menu. When provided, the dropdown menu uses the tabbed layout. */
  @Prop() tabOptions?: KsDropdownMenu['tabOptions'];

  /** An array of IDs representing the currently active items in the dropdown menu. */
  @Prop() @Vue2ValueFix() value?: (string | number)[];
  /** The default value of the dropdown menu. */
  @Prop() defaultValue?: (string | number)[];
  /** The ID of the currently active tab in the dropdown menu. This prop only applies when `tabOptions` is provided. */
  @Prop() activeTabId?: string;

  /** Indicates whether the dropdown menu list is selectable. */
  @Prop() selectable = false;
  /** Controls whether the dropdown menu list supports multiple selection. When true, the dropdown menu list allows multiple selections. */
  @Prop() multiple?: boolean;
  /** The placement of the dropdown menu. */
  @Prop() placement: Placement = 'bottom-start';
  /** Indicates whether the dropdown menu is currently open. */
  @Prop() open?: boolean;
  /** Indicates whether the dropdown menu is default open. */
  @Prop() defaultOpen?: boolean;
  @Uncontrollable('open', 'defaultOpen', 'ksOpenChange') @State() internalOpenState?: boolean;
  /** Popover props. */
  @Prop() popoverProps?: DropdownPopoverProps;
  /** The list has a default height, available for `popupHeight` to override. If `"auto"` is passed, the height will be auto-scaled. */
  @Prop() popupHeight: string | number | { min?: string | number; max?: string | number } = { max: 381 };
  /** The width of the dropdown menu. */
  @Prop() popupWidth?: string | number | { min?: string | number; max?: string | number };
  /** Search config for the dropdown menu. Pass a config object to enable search and customize its behavior. */
  @Prop() search?: DropdownSearchConfig;
  /** The current value of the search input in the dropdown menu. */
  @Prop() searchValue?: string;

  /** Whether the dropdown menu panel is loading. This controls the menu content separately from the trigger button `loading` state. */
  @Prop() loadingMenu?: boolean;

  /** Whether the dropdown menu is loading more. */
  @Prop() loadingMore?: boolean;

  /** Indicates whether the dropdown menu list failed to load. */
  @Prop() loadFailed?: boolean;

  /** Indicates whether the dropdown menu list failed to load more items. */
  @Prop() loadMoreFailed?: boolean;

  /** Whether to hide the divider between groups of items. */
  @Prop() hideGroupDivider = false;

  /**
   * @private
   * @deprecated
   * Whether to hide the title of the search result.
   */
  @Prop() hideSearchResultTitle = false;

  /** Whether to enable virtualization. */
  @Prop() virtual?: boolean | { estimatedItemHeight: number | ((item: FlattenNode<DropdownItem>) => number) };

  // 按钮相关属性
  /** The size of the button. */
  @Prop() size: BtnSize = 'md';
  /** The variant of the button. */
  @Prop() variant: BtnVariant = 'default';
  /** Indicates whether the button is in a loading state. */
  @Prop() loading = false;
  /** Indicates whether the button is disabled. */
  @Prop() disabled = false;

  /** Indicates whether the button is icon only. Icon only buttons has more compact style. */
  @Prop() iconOnly = false;

  /** Custom props for Dropdown Button parts. Supports `button` and `dropdown` sub-part props. */
  @Prop() partProps?: DropdownButtonPartProps;

  // 透传 dropdown-menu 的所有事件
  /** Custom event triggered when the value changes in the dropdown menu. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<DetailArgs<[Value[], DropdownItem[]]>>;
  @Listen('ksChange')
  onKsChange({ detail: value }: CustomEvent<DetailArgs<[Value[], DropdownItem[]]>>) {
    sendActionTracking(this.el, {
      eventType: 'change',
      subEventType: 'items',
      componentParams: { value },
    });
  }
  /** Custom event triggered when the search input value changes in the dropdown menu. */
  @Event({ bubbles: false, composed: false }) ksSearch!: EventEmitter<string>;
  @Listen('ksSearch')
  onKsSearch({ detail: searchValue }: CustomEvent<string>) {
    sendActionTracking(this.el, {
      eventType: 'change',
      subEventType: 'search',
      componentParams: { searchValue },
    });
  }

  /** Custom event triggered when the open state of the dropdown menu changes. */
  @Event({ bubbles: false, composed: false }) ksOpenChange!: EventEmitter<boolean>;
  @Listen('ksOpenChange')
  onKsOpenChange({ detail: open }: CustomEvent<boolean>) {
    if (open) {
      sendExposeTracking(this.el, { eventType: 'popup' });
      sendDurationTracking(this.el, { eventType: 'popup', reset: true });
    } else {
      sendDurationTracking(this.el, { eventType: 'popup' });
    }
  }

  /** Custom event triggered when the active tab changes in the dropdown menu. */
  @Event({ bubbles: false, composed: false }) ksActiveTabChange!: EventEmitter<string>;
  @Listen('ksActiveTabChange')
  onKsActiveTabChange({ detail: tabId }: CustomEvent<string>) {
    sendActionTracking(this.el, {
      eventType: 'change',
      subEventType: 'tabs',
      componentParams: { tabId },
    });
  }

  // 透传 dropdown-menu 的所有插槽
  /** The slot at the top of the list (scrollable area in DropdownMenu). */
  @Slot({ slotname: 'listHeader' }) private listHeaderSlots?: Slots;

  /** The slot to be displayed when the list is empty. */
  @Slot({ slotname: 'empty' }) private emptySlot?: Slots;

  /** The slot to be displayed when the list fails to load. */
  @Slot({ slotname: 'loadFailure' }) private loadFailureSlot?: Slots;

  /** The slot to be displayed when the list fails to load more items. */
  @Slot({ slotname: 'loadMoreFailure' }) private loadMoreFailureSlot?: Slots;

  /** The slot rendered at the bottom of the dropdown menu panel. */
  @Slot({ slotname: 'popupFooter' }) private popupFooterSlot?: Slots;

  constructor() {
    registerPluginManager(this.el);
  }

  private _dropdownChildren: Array<HTMLElement> = [];
  componentWillLoad(): Promise<void> | void {
    this.el.childNodes.forEach((child: Node) => {
      if (child instanceof HTMLElement) {
        if (
          child.tagName.toLowerCase().startsWith('ks-dropdown-menu-tab-list') ||
          child.tagName.toLowerCase().startsWith('ks-dropdown-menu-list')
        ) {
          this._dropdownChildren.push(child);
        }
      }
    });
    this._dropdownChildren.forEach((child) => {
      this.el.removeChild(child);
    });
  }

  componentDidLoad(): void {
    this._dropdownChildren.forEach((child) => {
      child.setAttribute('key', Date.now().toString());
      this.dropdownMenuRef.appendChild(child);
    });
  }

  render() {
    return (
      <Host class="KsDropdownButton">
        <ks-dropdown-menu
          ref={(el) => (this.dropdownMenuRef = el!)}
          // props pass through
          options={this.options}
          tabOptions={this.tabOptions}
          value={this.value}
          defaultValue={this.defaultValue}
          activeTabId={this.activeTabId}
          selectable={this.selectable}
          multiple={this.multiple}
          placement={this.placement}
          open={this.internalOpenState}
          defaultOpen={this.defaultOpen}
          popoverProps={this.popoverProps}
          popupHeight={this.popupHeight}
          popupWidth={this.popupWidth}
          virtual={this.virtual}
          loading={this.loadingMenu}
          loadingMore={this.loadingMore}
          loadFailed={this.loadFailed}
          loadMoreFailed={this.loadMoreFailed}
          hideGroupDivider={this.hideGroupDivider}
          hideSearchResultTitle={this.hideSearchResultTitle}
          search={this.search}
          searchValue={this.searchValue}
          disabled={this.disabled || this.loading}
          // events pass through
          onKsChange={({ detail }) => {
            this.ksChange.emit(detail);
          }}
          onKsSearch={({ detail }) => {
            this.ksSearch.emit(detail);
          }}
          onKsOpenChange={({ detail }) => {
            this.internalOpenState = detail;
          }}
          onKsActiveTabChange={({ detail }) => {
            this.ksActiveTabChange.emit(detail);
          }}
          data-testid="ks-dropdown-button-index-guDJGx"
          {...getPartProps(this, 'dropdown')}
          wrapWithSlot={this.wrapWithSlot}
          setDynamicRenderDeps={(children: unknown[], getPassThroughSlots?: () => VNode[]) => {
            this.setDynamicRenderDeps(children, () => getPassThroughSlots?.() || []);
            this.passThroughSlots = getPassThroughSlots?.() || [];
          }}
        >
          <ks-button
            part="button"
            class="button"
            variant={this.variant}
            size={this.size}
            loading={this.loading}
            disabled={this.disabled}
            iconOnly={this.iconOnly}
            forceActive={this.internalOpenState}
            onClick={() => {
              // We do not need to set open state here.
              // this.internalOpenState = !this.internalOpenState;
              sendActionTracking(this.el, {
                eventType: 'click',
                subEventType: 'button',
              });
            }}
            data-testid="ks-dropdown-button-index-cswyDL"
            {...getPartProps(this, 'button')}
          >
            <slot></slot>
            <KsIconChevronDown
              size={this.size === 'md' ? 16 : 14}
              class={{
                [`${prefix}__icon`]: true,
                [`${prefix}__icon--reverse`]: Boolean(this.internalOpenState),
              }}
            />
          </ks-button>

          {this.listHeaderSlots && <slot name="listHeader" slot="listHeader" />}
          {this.emptySlot && <slot name="empty" slot="empty" />}
          {this.loadFailureSlot && <slot name="loadFailure" slot="loadFailure" />}
          {this.loadMoreFailureSlot && <slot name="loadMoreFailure" slot="loadMoreFailure" />}
          {this.popupFooterSlot && <slot name="popupFooter" slot="popupFooter" />}
          {this.passThroughSlots}
        </ks-dropdown-menu>
      </Host>
    );
  }

  @State() private passThroughSlots: VNode[] = [];
  /**
   * @private */
  @Prop() wrapWithSlot: (slotName: string, children: unknown) => unknown = () => [];
  /**
   * @private */
  @Prop() setDynamicRenderDeps: (children: unknown[], getPassThroughSlots?: () => VNode[]) => void = noop;
}
